import{_ as t,o as r,c as a,ah as o}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Research: The \\"Postenschacher\\" Case (August Wöginger)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/postenschacher-woeginger.md","filePath":"en/recherche/postenschacher-woeginger.md"}'),i={name:"en/recherche/postenschacher-woeginger.md"};function n(s,e,h,u,l,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="research-the-postenschacher-case-august-woginger" tabindex="-1">Research: The &quot;Postenschacher&quot; Case (August Wöginger) <a class="header-anchor" href="#research-the-postenschacher-case-august-woginger" aria-label="Permalink to &quot;Research: The &quot;Postenschacher&quot; Case (August Wöginger)&quot;">​</a></h1><p><strong>The case of the parliamentary group leader: When political intervention meets abuse of office.</strong></p><p>Parallel to the historical machinations of the Horten era, the current political landscape of Austria provides ample material for our mockumentary. A prime example of modern intervention is the trial against ÖVP parliamentary group leader <strong>August Wöginger</strong>, who is currently (as of February/March 2026) standing trial at the Linz Regional Court.</p><hr><h2 id="the-allegation-incitement-to-abuse-of-office" tabindex="-1">The Allegation: Incitement to Abuse of Office <a class="header-anchor" href="#the-allegation-incitement-to-abuse-of-office" aria-label="Permalink to &quot;The Allegation: Incitement to Abuse of Office&quot;">​</a></h2><p>The Economic and Corruption Prosecutor&#39;s Office (WKStA) accuses August Wöginger of intervening with <strong>Thomas Schmid</strong> (then Secretary General in the Ministry of Finance) in 2017.</p><ul><li><strong>The Goal:</strong> An ÖVP mayor from the Schärding district was to be given the post of head of the Braunau-Ried-Schärding tax office.</li><li><strong>The Problem:</strong> Another applicant, Christa Scharf, was considered technically better qualified by the Federal Administrative Court. However, she was bypassed.</li><li><strong>Wöginger&#39;s Role:</strong> He is considered the &quot;inciter,&quot; as he allegedly encouraged the decision-makers to make the unlawful appointment.</li></ul><hr><h2 id="current-status-of-the-court-hearing-february-2026" tabindex="-1">Current Status of the Court Hearing (February 2026) <a class="header-anchor" href="#current-status-of-the-court-hearing-february-2026" aria-label="Permalink to &quot;Current Status of the Court Hearing (February 2026)&quot;">​</a></h2><h2 id="current-status-of-the-court-hearing-march-2026" tabindex="-1">Current Status of the Court Hearing (March 2026) <a class="header-anchor" href="#current-status-of-the-court-hearing-march-2026" aria-label="Permalink to &quot;Current Status of the Court Hearing (March 2026)&quot;">​</a></h2><p>After an originally planned diversion (payment of a fine without admission of guilt) was overturned by the Linz Higher Regional Court, the main trial is now underway.</p><h3 id="_1-testimonies-of-co-defendants-february-2026" tabindex="-1">1. Testimonies of Co-Defendants (February 2026) <a class="header-anchor" href="#_1-testimonies-of-co-defendants-february-2026" aria-label="Permalink to &quot;1. Testimonies of Co-Defendants (February 2026)&quot;">​</a></h3><p>The two co-accused finance officials were questioned separately:</p><ul><li><strong>The Commission Chairman (Siegfried M.):</strong> Pleads &quot;not guilty.&quot;</li><li><strong>The Personnel Representative (Herbert B.):</strong> Admitted that Thomas Schmid asked him to support the mayor but denies manipulations. He described Schmid&#39;s statements on March 3rd as a &quot;lie.&quot;</li></ul><h3 id="_2-testimony-of-august-woginger-march-3-2026" tabindex="-1">2. Testimony of August Wöginger (March 3, 2026) <a class="header-anchor" href="#_2-testimony-of-august-woginger-march-3-2026" aria-label="Permalink to &quot;2. Testimony of August Wöginger (March 3, 2026)&quot;">​</a></h3><p>Today, the parliamentary group leader himself took the witness stand:</p><ul><li><strong>Plea:</strong> &quot;Not guilty.&quot; Wöginger emphasized that the first diversion was not an admission of guilt, but an attempt to end the proceedings quickly to protect his family.</li><li><strong>Key Statement:</strong> &quot;I would not do it today.&quot; He expressed regret over forwarding the application (&quot;I am sorry for what my request for review triggered&quot;) but denies any incitement to abuse of office. He maintained it was merely a &quot;constituent concern.&quot;</li></ul><h3 id="_3-the-next-steps" tabindex="-1">3. The Next Steps <a class="header-anchor" href="#_3-the-next-steps" aria-label="Permalink to &quot;3. The Next Steps&quot;">​</a></h3><ul><li><strong>March 5, 2026:</strong> Testimony of the bypassed competitor, Christa Scharf.</li><li><strong>March 9, 2026:</strong> Expected testimony of star witness <strong>Thomas Schmid</strong>.</li><li><strong>April 21, 2026:</strong> Targeted verdict.</li></ul><h3 id="_4-civil-resistance-satire-march-3-2026" tabindex="-1">4. Civil Resistance &amp; Satire (March 3, 2026) <a class="header-anchor" href="#_4-civil-resistance-satire-march-3-2026" aria-label="Permalink to &quot;4. Civil Resistance &amp; Satire (March 3, 2026)&quot;">​</a></h3><p>In front of the court building in Linz, a protester (Andreas Röbl) causes a stir with a large sign:</p><ul><li><strong>Motto:</strong> &quot;Oh du liaba Augustin&quot; – based on the famous folk song, but aimed at the parliamentary group leader.</li><li><strong>Message:</strong> The protest is directed against the system of political patronage, which is described as the &quot;Austrian disease.&quot;</li><li><strong>Symbolism:</strong> For the protester, it is not the politician but the bypassed official Christa Scharf who is the actual hero, as she resisted the overwhelming power of the structures.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>In our mockumentary, we draw parallels between the historical favoring of &quot;friends&quot; (such as Helmut Horten by the Nazi regime) and modern political patronage.</p><ul><li><strong>The Motif of &quot;Intervention&quot;:</strong> It shows that power is consolidated not only through money (donations) but also through access to state structures (appointments).</li><li><strong>Satirical Implementation:</strong> We plan a scene in which a fictional politician attempts to reinterpret an intervention as &quot;regional structural development&quot; – very much in the style of Wöginger&#39;s line of defense.</li></ul><hr><p><em>Sources: Current reporting (Trend, Krone, Kurier, OE24) from February 27, 2026, files of the WKStA.</em></p>',28)])])}const f=t(i,[["render",n]]);export{d as __pageData,f as default};
